import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第二十九卦 坎 坎为水 坎上坎下","description":"周易 - 第二十九卦 坎 坎为水 坎上坎下","frontmatter":{"title":"第二十九卦 坎 坎为水 坎上坎下","description":"周易 - 第二十九卦 坎 坎为水 坎上坎下"},"headers":[],"relativePath":"zh/classics/zhouyi/030.md","filePath":"zh/classics/zhouyi/030.md"}'),l={name:"zh/classics/zhouyi/030.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="坎" tabindex="-1">坎 <a class="header-anchor" href="#坎" aria-label="Permalink to “坎”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>习坎，有孚，维心亨，行有尚。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>习坎，重险也。水流而不盈，行险而不失其信。维心亨，乃以刚中也。行有尚，往有功也。天险不可升也，地险山川丘陵也，王公设险以守其国，坎之时用大矣哉！</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>水洊至，习坎；君子以常德行，习教事。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>习坎，入于坎窞，凶。象曰：习坎入坎，失道凶也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>坎有险，求小得。象曰：求小得，未出中也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>来之坎坎，险且枕，入于坎窞，勿用。象曰：来之坎坎，终无功也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>樽酒簋贰，用缶，纳约自牖，终无咎。象曰：樽酒簋贰，刚柔际也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>坎不盈，只既平，无咎。象曰：坎不盈，中未大也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>用徽繹，置于丛棘，三岁不得，凶。象曰：上六失道，凶三岁也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
